  $cppjjson${"slug": "class-piano-piano-proficiency", "title": "Class Piano / Piano Proficiency", "description": "A group piano course for undergraduate music majors focused on functional keyboard fluency. Students develop keyboard geography, technique, reading in both clefs, scales, cadences, harmonization, sight-reading, transposition, accompaniment patterns, repertoire, and proficiency exam readiness while connecting piano skills to theory, ear training, ensemble work, and practical musicianship.", "topics": [{"id": "e93973ff-472c-4ccc-b786-3a5a92c3b0d6", "type": "topic", "title": "Keyboard Geography", "description": "This opening unit builds immediate orientation at the keyboard so students can think musically without hunting for notes.", "children": [{"id": "44616cbf-8365-4a53-9c7d-e9ab9ec41cb6", "type": "subtopic", "title": "Octaves, registers, and landmarks", "children": [{"id": "18641ae3-a34e-4977-969a-744619064c9f", "type": "concept", "title": "black-key groups"}, {"id": "2fd73f47-57e3-4461-9ba3-e8071273d8b6", "type": "concept", "title": "middle C and octave Cs"}, {"id": "9bd1d854-0a1f-48bc-b4c5-4e80136527b6", "type": "concept", "title": "register labels"}], "description": "Students learn the physical map of the keyboard and how pitch names repeat across registers."}, {"id": "5145215d-61c3-4065-97d1-6272e7af558b", "type": "subtopic", "title": "Finger numbers and hand position", "children": [{"id": "1191a761-8959-4871-9e89-b0fcc0f530d8", "type": "concept", "title": "finger numbers"}, {"id": "d6399036-c4f0-41a6-9f74-1d5415be8827", "type": "concept", "title": "five-finger position"}, {"id": "d211da4c-dd84-4d9f-a418-5d55f47332d5", "type": "concept", "title": "wrist alignment"}], "description": "The class establishes efficient finger numbering, relaxed hand shape, and basic coordination."}, {"id": "1c03f59e-f5d1-488f-831c-12b991370498", "type": "subtopic", "title": "Keyboard-to-staff connection", "children": [{"id": "05053695-95d9-49c3-947d-c286d7423290", "type": "concept", "title": "grand staff"}, {"id": "554c1d7d-69be-4ab0-9b20-e94dc51746b0", "type": "concept", "title": "ledger lines"}, {"id": "e1b451cc-edca-4515-89fc-4588501667e3", "type": "concept", "title": "directional reading"}], "description": "Students connect keyboard locations to treble and bass clef notation."}]}, {"id": "f46fd046-3a67-4a8d-8856-265c97dfd4b1", "type": "topic", "title": "Five-Finger Patterns and Scales", "description": "Patterns and scales develop technique, key fluency, and the muscle memory students need for harmonization and repertoire.", "children": [{"id": "26bad8e0-cf54-43f5-9550-e5d699ecb06f", "type": "subtopic", "title": "Major and minor five-finger patterns", "children": [{"id": "2e0b069f-ac20-4196-b0bf-ce2244ebb280", "type": "concept", "title": "major patterns"}, {"id": "c81be4b9-e885-40b5-8a5e-12eb23e4a486", "type": "concept", "title": "natural minor"}, {"id": "e6dfcfc7-0847-48d8-9425-0a468f22be2e", "type": "concept", "title": "harmonic minor color"}], "description": "Students practice common tonal patterns that support reading, transposition, and improvisation."}, {"id": "739e91ba-2342-4ffa-b102-9cfaf16bcb85", "type": "subtopic", "title": "Scale fingering and coordination", "children": [{"id": "c7c3567a-9680-4897-918f-d2ea68454929", "type": "concept", "title": "thumb-under motion"}, {"id": "179448c9-64d1-41cf-ba30-f0ab6cde3f41", "type": "concept", "title": "parallel motion"}, {"id": "19c656d6-ef56-4f54-aa61-6cf5081e4b26", "type": "concept", "title": "contrary motion"}], "description": "The unit introduces efficient thumb crossings and hand coordination for common scales."}, {"id": "28207956-1211-49af-b615-663413d004c1", "type": "subtopic", "title": "Technique and tone", "children": [{"id": "3c087d13-f169-422e-bbe8-f7ada2f67864", "type": "concept", "title": "relaxed weight"}, {"id": "5012e97e-f28e-4556-8cfe-2e249a1d7cfc", "type": "concept", "title": "legato/staccato"}, {"id": "2abb3be7-9793-4de5-bb2b-89be20f2d015", "type": "concept", "title": "dynamic control"}], "description": "Students learn to play with healthy movement, evenness, articulation, and musical sound."}]}, {"id": "c8df773b-179d-48d3-9cd8-a2f819811943", "type": "topic", "title": "Reading in Both Clefs", "description": "Music majors need functional fluency in treble and bass clefs for theory, rehearsal, accompanying, and score study.", "children": [{"id": "d81b6dd3-bbdf-4f4a-8021-3a7ba187d3c9", "type": "subtopic", "title": "Grand staff reading", "children": [{"id": "80d42282-9cf9-47b9-ae6b-ec7fa2f48bfa", "type": "concept", "title": "treble clef"}, {"id": "913dfd2f-54d9-451e-aa2d-5887dee4264a", "type": "concept", "title": "bass clef"}, {"id": "495de182-d282-4376-a9ce-bbe8c0dfd310", "type": "concept", "title": "staff relationships"}], "description": "Students practice reading both staves as one coordinated musical system."}, {"id": "e79d4712-9925-46e3-8253-38e46dfb3e1a", "type": "subtopic", "title": "Rhythm and coordination", "children": [{"id": "90a8a9cf-63fd-4478-9737-b9a030f5ff0f", "type": "concept", "title": "counting systems"}, {"id": "d963c3ab-8beb-49f8-af4d-cb9ba789151d", "type": "concept", "title": "ties and rests"}, {"id": "b38988dd-bc65-4764-842e-d3e716e73039", "type": "concept", "title": "hands-together rhythm"}], "description": "The class links pitch reading with steady pulse, subdivision, and two-hand independence."}, {"id": "72128dee-9726-4499-9bee-b992dee28ba8", "type": "subtopic", "title": "Score-reading habits", "children": [{"id": "c4a2f3dc-8bf6-470a-b9ee-440ee3f08ea2", "type": "concept", "title": "key signature scan"}, {"id": "f8ef9fcb-6466-459f-8c3e-a06ada93c874", "type": "concept", "title": "pattern spotting"}, {"id": "39d535ac-aa8f-4b7f-a0ad-055e3158a621", "type": "concept", "title": "fingering decisions"}], "description": "Students learn previewing strategies that make unfamiliar music less overwhelming."}]}, {"id": "c47c39e8-55c9-4b01-8543-84616c51a7fb", "type": "topic", "title": "Chord Progressions and Cadences", "description": "This unit gives students the keyboard harmony needed for theory application, accompaniment, and functional musicianship.", "children": [{"id": "dad01be4-421e-4f4a-9d43-ccf5b3fcfbb6", "type": "subtopic", "title": "Triads and inversions", "children": [{"id": "36a1b3ec-5076-4307-8d72-2c9d6c49871e", "type": "concept", "title": "root position"}, {"id": "63d36881-77b6-4b1f-91f4-dc54563e375e", "type": "concept", "title": "first inversion"}, {"id": "a6f7685b-d9b2-4b45-bcfd-da4e5d4cd8f9", "type": "concept", "title": "second inversion"}], "description": "Students learn to build and play chords smoothly in multiple positions."}, {"id": "c7c88d9f-d38c-4fbb-96db-a5b378d93bad", "type": "subtopic", "title": "Primary progressions", "children": [{"id": "ad251adb-e5b2-4ed0-baa1-ce21789927d0", "type": "concept", "title": "I-IV-V-I"}, {"id": "3b8230eb-257f-435c-867e-06716466a383", "type": "concept", "title": "ii-V-I awareness"}, {"id": "e8066848-2d99-404c-856e-e088a7b70f32", "type": "concept", "title": "minor-key cadences"}], "description": "The class practices I, IV, V, and V7 progressions in common major and minor keys."}, {"id": "142ba35c-76f0-4f04-9e9a-25ba704bf58d", "type": "subtopic", "title": "Cadence types", "children": [{"id": "b0969628-7e6e-4cfd-8879-df411a96082b", "type": "concept", "title": "authentic cadence"}, {"id": "36387343-b38d-44f6-936f-a4143f198f5e", "type": "concept", "title": "half cadence"}, {"id": "3d845971-6d51-48cc-81ca-0f1c026d56ea", "type": "concept", "title": "plagal cadence"}], "description": "Students connect harmonic closure to musical phrase structure and style."}]}, {"id": "51369259-ed6c-469c-8486-58fa7cb08d96", "type": "topic", "title": "Harmonization of Melodies", "description": "Harmonization turns theoretical chord knowledge into practical keyboard musicianship for teaching, arranging, and rehearsal work.", "children": [{"id": "c11678f0-64c7-4622-bddf-17a40909728c", "type": "subtopic", "title": "Harmonic analysis of simple melodies", "children": [{"id": "de6b0677-f61a-4338-a6fc-11716f26d1bc", "type": "concept", "title": "phrase endings"}, {"id": "6e955f24-a68c-4e70-94d7-e93ea45289ef", "type": "concept", "title": "non-chord tones"}, {"id": "bc65e32e-b753-4359-a523-f2d8c10d2fc1", "type": "concept", "title": "harmonic rhythm"}], "description": "Students identify phrase points, implied harmonies, and cadential goals."}, {"id": "54bb7c02-0c9d-4c3d-a880-6dd859d13dcb", "type": "subtopic", "title": "Block-chord harmonization", "children": [{"id": "11f99a0c-8a47-4c2a-bd5f-e7b2f7cbb682", "type": "concept", "title": "root-position chords"}, {"id": "0401250f-abb0-447d-adf1-dcda5e609f4d", "type": "concept", "title": "inverted chords"}, {"id": "14db1d17-74c3-4d62-9b98-50600d349112", "type": "concept", "title": "voice leading"}], "description": "The unit begins with simple left-hand or two-hand chord settings."}, {"id": "52e50bb1-b443-4520-ac5b-99cf85beab20", "type": "subtopic", "title": "Style-appropriate realization", "children": [{"id": "b39a1e44-4a7c-42f6-a835-27c8031e97a8", "type": "concept", "title": "broken chords"}, {"id": "3611bc8c-5937-42c9-baec-208f7e47265c", "type": "concept", "title": "waltz bass"}, {"id": "0053ef26-14e7-4e9c-81a7-7d05bc619e19", "type": "concept", "title": "lead-sheet symbols"}], "description": "Students experiment with accompaniments that fit folk, classical, pop, and classroom settings."}]}, {"id": "775d8aa1-0994-45cd-bb21-fc4c2d11ef3a", "type": "topic", "title": "Sight-Reading", "description": "Sight-reading develops practical fluency: the ability to keep going musically while processing unfamiliar notation.", "children": [{"id": "d0b04398-516a-4129-91de-f115015f2f2b", "type": "subtopic", "title": "Preview strategy", "children": [{"id": "43df54a7-faf0-4f9e-b162-21b54ef2df6d", "type": "concept", "title": "key and meter"}, {"id": "a122c294-f09f-432f-9f62-29d150e79de9", "type": "concept", "title": "hand position"}, {"id": "050e87f3-1cd3-41c8-8889-52f9d4e495fb", "type": "concept", "title": "repeated patterns"}], "description": "Students learn to scan before playing so they can anticipate the main challenges."}, {"id": "a7e07eec-b989-4466-9232-079c43a2315b", "type": "subtopic", "title": "Continuity and recovery", "children": [{"id": "9551f762-57b1-4c5b-873b-d57a24225c8d", "type": "concept", "title": "steady tempo"}, {"id": "27ea8fca-3446-47e0-af91-20110fb00397", "type": "concept", "title": "error recovery"}, {"id": "5c25db06-119a-449f-bb39-f2dd63a5174f", "type": "concept", "title": "prioritizing rhythm"}], "description": "The class emphasizes pulse, simplification, and recovery over stopping to correct every detail."}, {"id": "9c6d559b-a211-490b-a114-d735f5c4f067", "type": "subtopic", "title": "Progressive reading practice", "children": [{"id": "1128ba7a-4b59-4634-aa93-e3d02a9e8155", "type": "concept", "title": "daily drills"}, {"id": "0341a59c-fe03-4dc2-a485-c042b6f210dd", "type": "concept", "title": "duets"}, {"id": "db6b6c5e-5121-4a15-81f6-1270a0307f9d", "type": "concept", "title": "four-measure excerpts"}], "description": "Students build speed and confidence through frequent short examples."}]}, {"id": "199cb973-2c54-4b37-828f-1c36b4790edf", "type": "topic", "title": "Transposition", "description": "Transposition helps students understand key relationships and support singers, instrumentalists, and classroom music-making.", "children": [{"id": "4b7ec3d7-3662-4873-8005-44d05baf6864", "type": "subtopic", "title": "Interval and scale-degree thinking", "children": [{"id": "586e86dc-51a9-4b36-acd1-c2a8d19d0cfc", "type": "concept", "title": "scale degrees"}, {"id": "02eb1d8a-5abe-4e73-bfe2-435541106b9b", "type": "concept", "title": "interval patterns"}, {"id": "5c4319f5-e713-49d3-ae2d-f90c499264be", "type": "concept", "title": "tonic orientation"}], "description": "Students learn to transpose by function rather than note-by-note guessing."}, {"id": "75a28373-3518-4d04-bef1-011a58b38898", "type": "subtopic", "title": "Melody transposition",