bc1aded4", "type": "topic", "title": "Improvisation, Score Reading, and Musicianship Integration", "description": "This added capstone unit connects class piano to the broader skills expected of versatile undergraduate musicians.", "children": [{"id": "93ee452e-0985-4f72-9001-e67ccc4f22e3", "type": "subtopic", "title": "Improvisation from patterns", "children": [{"id": "58dfabc4-628a-419f-ac87-13c8b6b93bc4", "type": "concept", "title": "call and response"}, {"id": "aabb6d43-8462-429e-949a-64cafd05412e", "type": "concept", "title": "question-answer phrases"}, {"id": "a5ae49c5-5ee1-4f2d-a013-57e71ebe2aae", "type": "concept", "title": "ostinato"}], "description": "Students use scales, chords, and rhythms to invent short musical ideas."}, {"id": "1077d6c2-c4e5-497c-9a85-07582cb4bc22", "type": "subtopic", "title": "Open-score and choral reading", "children": [{"id": "d85734e6-a3b7-4b81-8bdd-7e24c4538267", "type": "concept", "title": "SATB reduction"}, {"id": "a161b091-f7a2-457b-ba06-dcb090d78ae4", "type": "concept", "title": "two-staff compression"}, {"id": "a01e4797-1fd1-47db-b290-86357d49a36c", "type": "concept", "title": "cue reading"}], "description": "The class introduces simplified score reading for conductors, educators, composers, and theorists."}, {"id": "373c6251-fc78-41f7-bea5-e244efe1246f", "type": "subtopic", "title": "Integrated musicianship task", "children": [{"id": "6de18552-43fa-4db1-a46b-7e764618557c", "type": "concept", "title": "melody plus chords"}, {"id": "1645fca8-8f89-4220-8420-8f78df2f701c", "type": "concept", "title": "transpose and accompany"}, {"id": "520ad7b8-1c35-4c05-9608-c263f1ba44e5", "type": "concept", "title": "sing/play coordination"}], "description": "Students combine reading, harmonization, transposition, and accompaniment in one practical assignment."}]}], "dbBacked": true}$cppjjson$::jsonb,
