set
  title = 'Class Piano / Piano Proficiency',
  goal = 'Class Piano / Piano Proficiency',
  summary = 'A group piano course for undergraduate music majors focused on functional keyboard fluency. Students develop keyboard geography, technique, reading in both clefs, scales, cadences, harmonization, sight-reading, transposition, accompaniment patterns, repertoire, and proficiency exam readiness while connecting piano skills to theory, ear training, ensemble work, and practical musicianship.',
  data = $cppjjson${"slug": "class-piano-piano-proficiency", "title": "Class Piano / Piano Proficiency", "description": "A group piano course for undergraduate music majors focused on functional keyboard fluency. Students develop keyboard geography, technique, reading in both clefs, scales, cadences, harmonization, sight-reading, transposition, accompaniment patterns, repertoire, and proficiency exam readiness while connecting piano skills to theory, ear training, ensemble work, and practical musicianship.", "topics": [{"id": "e93973ff-472c-4ccc-b786-3a5a92c3b0d6", "type": "topic", "title": "Keyboard Geography", "description": "This opening unit builds immediate orientation at the keyboard so students can think musically without hunting for notes.", "children": [{"id": "44616cbf-8365-4a53-9c7d-e9ab9ec41cb6", "type": "subtopic", "title": "Octaves, registers, and landmarks", "children": [{"id": "18641ae3-a34e-4977-969a-744619064c9f", "type": "concept", "title": "black-key groups"}, {"id": "2fd73f47-57e3-4461-9ba3-e8071273d8b6", "type": "concept", "title": "middle C and octave Cs"}, {"id": "9bd1d854-0a1f-48bc-b4c5-4e80136527b6", "type": "concept", "title": "register labels"}], "description": "Students learn the physical map of the keyboard and how pitch names repeat across registers."}, {"id": "5145215d-61c3-4065-97d1-6272e7af558b", "type": "subtopic", "title": "Finger numbers and hand position", "children": [{"id": "1191a761-8959-4871-9e89-b0fcc0f530d8", "type": "concept", "title": "finger numbers"}, {"id": "d6399036-c4f0-41a6-9f74-1d5415be8827", "type": "concept", "title": "five-finger position"}, {"id": "d211da4c-dd84-4d9f-a418-5d55f47332d5", "type": "concept", "title": "wrist alignment"}], "description": "The class establishes efficient finger numbering, relaxed hand shape, and basic coordination."}, {"id": "1c03f59e-f5d1-488f-831c-12b991370498", "type": "subtopic", "title": "Keyboard-to-staff connection", "children": [{"id": "05053695-95d9-49c3-947d-c286d7423290",