ition", "children": [{"id": "54422767-acc0-4786-aa73-333fc9724c7a", "type": "concept", "title": "whole-step transposition"}, {"id": "d3985c5c-8175-488d-af02-76288aa77132", "type": "concept", "title": "fifth relationship"}, {"id": "10039347-5391-4c99-b094-6a5d4fcd2be6", "type": "concept", "title": "minor-key examples"}], "description": "The unit begins with simple melodies moved to nearby keys."}, {"id": "736bb673-49a4-41d7-9b13-02847a62220f", "type": "subtopic", "title": "Harmonized transposition", "children": [{"id": "584b6339-48f6-4ae4-8ca8-7bfb70cc6471", "type": "concept", "title": "Roman numerals"}, {"id": "95b1e563-4fb5-4804-a9f0-d9898da075cb", "type": "concept", "title": "chord symbols"}, {"id": "e821da6c-e97e-4e4c-804f-70c88f7cb198", "type": "concept", "title": "cadence transfer"}], "description": "Students transpose progressions and short accompaniments with correct chord function."}]}, {"id": "38b147e1-4c7d-4ab7-9a45-1da75966fb26", "type": "topic", "title": "Accompaniment Patterns", "description": "Accompaniment patterns prepare students to support singers, instrumentalists, ensembles, and classroom activities at the keyboard.", "children": [{"id": "0b5f82a6-837e-43fa-921a-ecb1af40d7b3", "type": "subtopic", "title": "Left-hand patterns", "children": [{"id": "74caecfd-e5e1-4011-b379-77c6e8dd2d12", "type": "concept", "title": "blocked bass"}, {"id": "966979f1-6a55-43e6-8dd0-ffdcd2d1823a", "type": "concept", "title": "broken chords"}, {"id": "4cc8c0ec-a0c9-41db-901b-45b33be1e090", "type": "concept", "title": "Alberti-style patterns"}], "description": "Students learn basic accompaniment textures that can support many styles."}, {"id": "ebd3bf60-6052-4037-9ba4-c4aab2b7483b", "type": "subtopic", "title": "Lead-sheet realization", "children": [{"id": "f58d05dc-e9c2-4c6b-accd-768ed01f04c6", "type": "concept", "title": "slash chords"}, {"id": "22711768-c181-4925-908c-3131cfba81fd", "type": "concept", "title": "seventh chords"}, {"id": "9b079199-74ce-43d2-b7c4-4894be